algo='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seed = next(( (r,c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if seed is None:
        return out
    row_strength = max(sum(v == 8 for v in row) for row in grid)
    col_strength = max(sum(grid[r][c] == 8 for r in range(h)) for c in range(w))
    horizontal_bars = row_strength >= col_strength
    if horizontal_bars:
        bars = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= w * 0.5]
        start, tangent_n = seed[0], w
        tangent_start = seed[1]
        normal_n = h
        def openings(i): return [c for c,v in enumerate(grid[i]) if v == 0]
        def paint_normal(i, t):
            if out[i][t] == 0: out[i][t] = 2
        def paint_tangent(i, t):
            if out[i][t] == 0: out[i][t] = 2
    else:
        bars = [c for c in range(w) if sum(grid[r][c] == 8 for r in range(h)) >= h * 0.5]
        start, tangent_n = seed[1], h
        tangent_start = seed[0]
        normal_n = w
        def openings(i): return [r for r in range(h) if grid[r][i] == 0]
        def paint_normal(i, t):
            if out[t][i] == 0: out[t][i] = 2
        def paint_tangent(i, t):
            if out[t][i] == 0: out[t][i] = 2
    if not bars: return out
    # Travel along the axis perpendicular to the bars, away from the seed.
    candidates = [(b, 1 if b > start else -1) for b in bars if b != start]
    if not candidates: return out
    first, direction = min(candidates, key=lambda item: abs(item[0]-start))
    # Keep only the sequence of barriers in this travel direction.
    ordered = sorted((b for b in bars if (b-first)*direction >= 0), reverse=direction < 0)
    active = [tangent_start]
    def connect(adjacent, active_positions, portal_positions):
        reached = set()
        for x in active_positions:
            if x in portal_positions:
                paint_tangent(adjacent, x)
                reached.add(x)
                continue
            for step in (-1, 1):
                eligible = [q for q in portal_positions if (q-x)*step > 0]
                if eligible:
                    q = min(eligible, key=lambda q: abs(q-x))
                    end = q
                    reached.add(q)
                else:
                    end = 0 if step < 0 else tangent_n - 1
                lo, hi = sorted((x,end))
                for t in range(lo, hi+1): paint_tangent(adjacent,t)
        return sorted(reached)
    # Reach and pass through the first bar.
    adjacent = first - direction
    for i in range(start + direction, adjacent, direction):
        for t in active: paint_normal(i,t)
    active = connect(adjacent, active, openings(first))
    for t in active: paint_normal(first,t)
    # Traverse each later bar, projecting along the normal between barriers.
    for previous, current in zip(ordered, ordered[1:]):
        portal = openings(current)
        adjacent = current - direction
        for i in range(previous + direction, adjacent, direction):
            # The final adjacent line is the horizontal/vertical connector.
            if i != adjacent:
                for t in active: paint_normal(i,t)
        active = connect(adjacent, active, portal)
        for t in active: paint_normal(current,t)
    # Continue past the final barrier to the grid boundary.
    last = ordered[-1]
    for i in range(last + direction, normal_n if direction > 0 else -1, direction):
        for t in active: paint_normal(i,t)
    return out
